private void button1_Click(object sender, EventArgs e)
{
    // 1. Считывание и преобразование входных данных
    double price = Convert.ToDouble(textBox1.Text);
    int count = Convert.ToInt32(textBox2.Text);
    double discount = Convert.ToDouble(textBox3.Text);
    // 2. Проверка корректности
    if (price <= 0 || count <= 0 || discount < 0 || discount > 100)
        labelResult.Text = "Ошибка: некорректные входные данные!";
    else
    {
        // 3. Вычисление по модели и вывод
        double total = (price * count) * (1 - discount / 100.0);
        labelResult.Text = "Итого к оплате: " + total.ToString("0.##") + " тг";
    }
}

double a, b;
if (!double.TryParse(textBox1.Text, out a) ||
    !double.TryParse(textBox2.Text, out b))
{
    MessageBox.Show("Ошибка ввода: введите числовые значения!");
    return;
}
if (a <= 0 || b <= 0)
{
    MessageBox.Show("Ошибка: стороны должны быть строго больше нуля!");
    return;
}
double S = a * b;
labelResult.Text = "Площадь S = " + S.ToString();

double mas, h, imt = 0;
h = System.Convert.ToDouble(textBox1.Text);
mas = System.Convert.ToDouble(textBox2.Text);
if ((mas < 0 || mas > 200) || (h < 0 || h > 200))
    label4.Text = "Неверный ввод данных";
else
{
    imt = mas / (h * h);
    label4.Text = imt.ToString("0.##");
    if (radioButton3.Checked && !radioButton4.Checked)   // муж
    {
        if (imt > 18.4 && imt < 23.9) label5.Text = "норма";
        else if (imt < 18.5) label5.Text = "ниже нормы";
        else label5.Text = "выше нормы";
    }
    if (!radioButton3.Checked && radioButton4.Checked)   // жен
    {
        if (imt > 20 && imt < 25) label5.Text = "норма";
        else if (imt < 20.1) label5.Text = "ниже нормы";
        else label5.Text = "выше нормы";
    }
}

